), resolvido as (
 select s.*,k.id as kit_id,lm.id as lista_mae_id,lm.cod_item,lm.cod_produt,lm.descricao_oficial,lm.un
 from src s join public.kits k on k.codigo=s.kit_codigo
 left join lateral (
  select l.id,l.cod_item,l.cod_produt,l.descricao_oficial,l.un
  from public.lista_mae l where l.ativo is true and l.cod_item=s.cod_item_mapeado
  order by l.updated_at desc nulls last,l.created_at desc nulls last limit 1
 ) lm on true
)
insert into public.kit_itens(kit_id,lista_mae_id,quantidade,instalacao,observacao,fase,obrigatoriedade,modelos_aplicaveis,cod_item,versao,ativo,cod_produt,descricao_oficial,un,qtd_uni,quant_total,fonte,ordem,vinculo_status,vinculo_confianca,vinculo_observacao,elo_situacao,elo_confianca,elo_justificativa,elo_referencia,snapshot_origem,snapshot_at,vinculo_at)
select kit_id,lista_mae_id,quantidade_fonte,sistema,
 concat('Item fonte ',coalesce(item_origem,'-'),'; evidência=',coalesce(estado_evidencia,'-'),'; validação=',coalesce(status_validacao,'-'),case when coalesce(observacao_fonte,'')='' then '' else '; obs='||observacao_fonte end),
 'DOCUMENTAL','DOCUMENTAL_NAO_LIBERADO',modelo_codigo,cod_item,'DOC-2026-11-13',false,cod_produt,coalesce(descricao_oficial,descricao_fonte),coalesce(un,un_fonte),quantidade_fonte,quantidade_fonte,fonte,ordem_fonte,
 case when cod_item_mapeado is not null and lista_mae_id is null then 'GAP_CADASTRO' else vinculo_status end,
 vinculo_confianca,elo_justificativa,
 case when cod_item_mapeado is not null and lista_mae_id is null then 'GAP_CADASTRO_LISTA_MAE' else elo_situacao end,
 vinculo_confianca,elo_justificativa,
 concat('PORTFOLIO_MLTC_20261113|03_COMPOSICAO_TECNICA|linha=',ordem_fonte,'|item=',coalesce(item_origem,'-')),
 concat('descricao=',descricao_fonte,'; qtd=',quantidade_fonte,'; un=',un_fonte,'; fonte=',coalesce(fonte,'-')),
 now(),case when lista_mae_id is not null then now() else null end
from resolvido;

insert into public.mt_versoes_bom(tenant_id,modelo_id,versao,status,documento_engenharia_id)
select t.id,m.id,'DOC-2026-11-13','INCOMPLETA_DOCUMENTAL',d.id
from public.mt_tenants t join public.modelos m on m.codigo='MLT.C06'
left join lateral (select id from public.mt_documentos_engenharia where modelo_id=m.id order by id limit 1) d on true
where t.codigo='MULTITEINER'
on conflict (modelo_id,versao) do update set status=excluded.status,documento_engenharia_id=excluded.documento_engenharia_id,aprovado_em=null,aprovado_por=null,valido_desde=null,valido_ate=null;

