), alinhado as (
 select s.*,lm.id as lista_mae_id
 from src s join lateral (
  select l.id from public.lista_mae l where l.ativo is true and l.cod_item=s.cod_item_mapeado
  order by l.updated_at desc nulls last,l.created_at desc nulls last limit 1
 ) lm on true
 where s.promover_bom is true and s.elo_situacao='ALINHADO_DOCUMENTAL'
), agregado as (
 select modelo_codigo,lista_mae_id,sum(quantidade_fonte) quantidade,string_agg(distinct sistema,' + ' order by sistema) sistemas,
        string_agg(concat('linha ',ordem_fonte,': ',descricao_fonte),' | ' order by ordem_fonte) rastreio
 from alinhado group by modelo_codigo,lista_mae_id
)
insert into public.mt_bom_itens(bom_versao_id,lista_mae_id,quantidade,fator_perda,operacao_referencia,critico,observacoes)
select b.id,a.lista_mae_id,a.quantidade,0,a.sistemas,false,concat('RASCUNHO_DOCUMENTAL; não liberado para produção. Fonte: Portfólio MLT.C 13/11/2026. ',a.rastreio)
from agregado a join public.modelos m on m.codigo=a.modelo_codigo
join public.mt_versoes_bom b on b.modelo_id=m.id and b.versao='DOC-2026-11-13'
where b.status='RASCUNHO_DOCUMENTAL';

update public.elo_conhecimento_itens e set conteudo=jsonb_set(e.conteudo,'{integracao_kit_bom}',
 jsonb_build_object('kit_codigo',case e.chave_unica when 'PORTFOLIO_MLTC06_20261113' then 'KIT-MLTC06-DOCUMENTAL' when 'PORTFOLIO_MLTC10_20261113' then 'KIT-MLTC10-DOCUMENTAL' when 'PORTFOLIO_MLTC13_20261113' then 'KIT-MLTC13-DOCUMENTAL' when 'PORTFOLIO_MLTC20_20261113' then 'KIT-MLTC20-DOCUMENTAL' when 'PORTFOLIO_MLTC21_20261113' then 'KIT-MLTC21-DOCUMENTAL' when 'PORTFOLIO_MLTC25_20261113' then 'KIT-MLTC25-DOCUMENTAL' end,
 'versao','DOC-2026-11-13','status',case when e.chave_unica in ('PORTFOLIO_MLTC13_20261113','PORTFOLIO_MLTC20_20261113','PORTFOLIO_MLTC21_20261113') then 'RASCUNHO_DOCUMENTAL' else 'INCOMPLETA_DOCUMENTAL' end,
 'regra','Kit preserva lista documental completa; BOM contém apenas vínculos inequívocos sem GAP impeditivo; nenhuma versão está aprovada.'),true),updated_at=now()
where e.chave_unica in ('PORTFOLIO_MLTC06_20261113','PORTFOLIO_MLTC10_20261113','PORTFOLIO_MLTC13_20261113','PORTFOLIO_MLTC20_20261113','PORTFOLIO_MLTC21_20261113','PORTFOLIO_MLTC25_20261113');

update public.elo_conhecimento_itens set conteudo=jsonb_set(conteudo,'{integracao_kit_bom}',
 jsonb_build_object('versao','DOC-2026-11-13','kits_modelos',6,'linhas_documentais',122,'vinculos_lista_mae',47,'linhas_elegiveis_bom',27,'itens_bom_agregados',26,
 'regra','Sem promoção automática: kits não operacionais e BOMs apenas em rascunho/incompletas.'),true),updated_at=now()
where chave_unica='FAMILIA_MLTC_DRY_ADAPTADO';

create or replace view public.vw_elo_modelo_kit_bom_consolidado with (security_invoker=true) as
with bom_resumo as (
 select b.id bom_versao_id,b.modelo_id,b.versao,b.status,count(bi.id)::integer bom_itens_total,sum(bi.quantidade*coalesce(lm.valor_unitario,0)) bom_valor_estimado
 from public.mt_versoes_bom b left join public.mt_bom_itens bi on bi.bom_versao_id=b.id left join public.lista_mae lm on lm.id=bi.lista_mae_id
 group by b.id,b.modelo_id,b.versao,b.status
)
select m.id modelo_id,m.codigo modelo_codigo,m.nome modelo_nome,m.familia,k.id kit_id,k.codigo kit_codigo,k.nome kit_nome,k.tipo kit_tipo,k.versao kit_versao,k.ativo kit_operacional,
 ki.id kit_item_id,ki.ordem,ki.instalacao sistema,ki.quantidade quantidade_documental,ki.snapshot_origem item_fonte,ki.cod_item,ki.cod_produt,ki.descricao_oficial,ki.un,ki.lista_mae_id,
 ki.vinculo_status,ki.vinculo_confianca,ki.elo_situacao,ki.elo_justificativa,
 count(ki.id) over(partition by k.id)::integer kit_itens_total,
 count(ki.id) filter(where ki.lista_mae_id is not null) over(partition by k.id)::integer kit_itens_mapeados,
 count(ki.id) filter(where ki.elo_situacao='ALINHADO_DOCUMENTAL') over(partition by k.id)::integer kit_linhas_elegiveis_bom,
 count(ki.id) filter(where ki.elo_situacao<>'ALINHADO_DOCUMENTAL') over(partition by k.id)::integer kit_linhas_com_gap,
 br.bom_versao_id,br.status bom_status,coalesce(br.bom_itens_total,0) bom_itens_total,br.bom_valor_estimado,
 (bi.id is not null) item_incluido_bom,bi.quantidade quantidade_bom
from public.kits k join public.modelos m on m.id=k.modelo_id left join public.kit_itens ki on ki.kit_id=k.id
left join bom_resumo br on br.modelo_id=m.id and br.versao=k.versao
left join public.mt_bom_itens bi on bi.bom_versao_id=br.bom_versao_id and bi.lista_mae_id=ki.lista_mae_id and ki.elo_situacao='ALINHADO_DOCUMENTAL';

comment on view public.vw_elo_modelo_kit_bom_consolidado is 'Visão relacional que une modelo, kit documental, vínculo Lista Mãe e BOM por versão. Não representa liberação de produção; respeitar bom_status e elo_situacao.';

insert into public.tb_elo_eventos_governanca(evento,etapa,componente_orquestrador,componente_membro,status,referencia,detalhes)
select 'ORGANIZACAO_KITS_BOM_DOCUMENTAL_MLTC_20261113','FORGE_COMPOSICAO_DOCUMENTAL','ELO','FORGE_PRODUTOS','RASCUNHO_SEM_LIBERACAO_PRODUCAO','MLTC_KITS_BOM_DOC_20261113',
 jsonb_build_object('versao','DOC-2026-11-13','modelos',6,'kits_documentais',6,'linhas_documentais',122,'vinculos_lista_mae',47,'linhas_elegiveis_bom',27,'itens_bom_agregados',26,
 'regra','Kit completo preserva inclusive GAPs; mt_bom_itens recebe somente itens alinhados sem GAP impeditivo; C06/C10/C25 permanecem incompletos; nenhum BOM aprovado.')
where not exists(select 1 from public.tb_elo_eventos_governanca where evento='ORGANIZACAO_KITS_BOM_DOCUMENTAL_MLTC_20261113' and referencia='MLTC_KITS_BOM_DOC_20261113');
